from pathlib import Path
import argparse
import pandas as pd,numpy as np
from scipy.spatial.distance import jensenshannon

def main(argv=None):
 p=argparse.ArgumentParser();p.add_argument('--output-dir',type=Path,default=Path(__file__).resolve().parent/'nba_passing_output');p.add_argument('--destination',type=Path);a=p.parse_args(argv);root=a.output_dir;base=root/'onoff_dependency/predicted_actual_networks';out=a.destination or base;out.mkdir(parents=True,exist_ok=True);d=pd.read_csv(base/'prediction_actual_metrics.csv');players=pd.read_csv(root/'2025-26/team_season_topics/player_games.csv',dtype={'GAME_ID':str});players.GAME_ID=players.GAME_ID.str.zfill(10);games=pd.read_csv(root/'onoff_dependency/game_comparison_data.csv',dtype={'GAME_ID':str});games.GAME_ID=games.GAME_ID.str.zfill(10);roles=pd.read_csv(base/'player_role_changes.csv');rows=[];minutes=[]
 for z in d[d.regression_eligible].itertuples():
  F=pd.read_csv(base/z.team/'deleted_counts.csv',index_col=0);D=F.to_numpy();A=pd.read_csv(base/z.team/'actual_counts.csv',index_col=0).to_numpy();common=(D.sum(0)+D.sum(1)>0)&(A.sum(0)+A.sum(1)>0);C=D[np.ix_(common,common)];B=A[np.ix_(common,common)];tv=abs(C/C.sum()-B/B.sum()).sum()/2;both=(C.sum(1)>0)&(B.sum(1)>0);w=(C.sum(1)/C.sum()+B.sum(1)/B.sum())[both];w/=w.sum();js=sum(v*jensenshannon(C[i]/C[i].sum(),B[i]/B[i].sum(),base=2)**2 for i,v in zip(np.flatnonzero(both),w));rows.append(dict(team=z.team,all_player_edge_tv=z.edge_total_variation,common_player_edge_tv=tv,common_player_conditional_js=js,common_players=int(common.sum())))
  g=games[games.TEAM_ABBREVIATION.eq(z.team)];played=set(g[g.star_played].GAME_ID);missed=set(g[~g.star_played].GAME_ID);pt=players[players.TEAM_ABBREVIATION.eq(z.team)]
  for r in roles[roles.team.eq(z.team)].itertuples():
   person=pt[pt.PLAYER_ID.eq(r.player_id)];mp=person[person.GAME_ID.isin(played)].MIN.sum();ma=person[person.GAME_ID.isin(missed)].MIN.sum();minutes.append(dict(team=z.team,player_id=r.player_id,player_name=r.player_name,deleted_involvement_share=r.deleted_involvement_share,actual_involvement_share=r.actual_involvement_share,present_minutes_per_team_game=mp/z.present_games,absent_minutes_per_team_game=ma/z.absent_games,present_total_minutes=mp,absent_total_minutes=ma))
 pd.DataFrame(rows).to_csv(out/'common_player_network_check.csv',index=False);pd.DataFrame(minutes).to_csv(out/'minutes_and_role_diagnostics.csv',index=False)
 text=['# What differs between deleted-star and actual absence networks?','Analysis uses the 24 qualifying prior-on/off-selected-player comparisons. The all-30 PDF remains available. This is a deeper descriptive diagnostic, not an adjusted causal model.','## Overall','The deletion baseline preserves the remaining links’ relative allocation. Actual missed games change both player exposure and passing choices. Raw/equal-count direction agreement is only 13/24; the leading remaining involvement player matches in 12/24. These facts describe poor reproduction of observed networks, not a test of a trained forecasting model.','## Golden State: same leading hub, different distribution','Podziemski leads passing involvement in both the deleted and actual without-Curry graphs. Yet Pat Spencer rises from 5.11% to 13.64% of involvement; Gui Santos rises from 4.19% to 9.90%. Butler drops from 12.90% to 1.67%. The common main hub therefore hides a very different supporting network.','Spencer averages 6.35 minutes per team game in the Curry-played sample, versus 24.41 when Curry misses; Santos 9.95 versus 24.87; Butler 24.26 versus 3.64. These exposure changes make it unsafe to attribute all redistribution directly to Curry’s absence. Team-game averages include games each teammate did not play; they are not minutes per appearance.','## Denver: a changed hub and a changed available roster','The baseline’s largest remaining involvement player is Jamal Murray; the actual leader is Peyton Watson. Pickett rises from 3.94% to 14.77%, and Watson from 7.10% to 16.07%. Pickett averages 5.32 to 27.06 minutes per team game; Watson 16.22 to 31.88. Cameron Johnson has 25.35 to 0.00 minutes. Part of the large mismatch is other players’ unavailability, not a clean response to removing Jokić.','## Phoenix: entropy looks right while links are wrong','Deleted entropy 0.7347 and actual entropy 0.7351 are almost identical. Nevertheless edge-share distance is 0.291. Bouyea’s involvement share rises from 3.45% to 10.20%, while Gillespie falls from 21.32% to 14.54%. Similar entropy is not evidence of the same network: it summarizes variety without identifying who passes to whom.','## Shared-player check','Across qualified teams, median edge total-variation distance changes from 0.319 to 0.308 when both graphs are restricted to players with positive involvement in both contexts and renormalized. Thus roster entry/exit is not the only source of differences. Minutes, teammate combinations and recipient choices still differ within the common player set.','Memphis is a major exception: its distance falls from 0.725 to 0.428 under this restriction. Its particularly large full-network mismatch is substantially associated with a different participant set. This is not a formal causal decomposition, and the difference of distances is not an attributable percentage.','Common-player conditional JS is also exported. It compares recipient distributions of the same senders among the same recipient identities, weighting by average observed sender shares. It still does not equalize minutes, co-presence, opponents or game periods.','## Useful interpretation','Separate (1) changes in who plays and how much, (2) changes in players’ overall passing involvement, and (3) changes in which teammates receive their passes. The deleted baseline captures none of the replacement-minute mechanism. Its discrepancies are real descriptive network differences, but they mix lineup availability with offensive reorganization.','The strongest claim is that actual player absences produce networks that cannot generally be reconstructed by deleting the star’s connections alone. Do not label every mismatch tactical adaptation or player dependency.']
 (out/'DETAILED_NETWORK_DIFFERENCES.md').write_text('\n\n'.join(text));print(pd.DataFrame(rows).iloc[:,1:4].median().to_string());return 0
if __name__=='__main__':raise SystemExit(main())
